ssize_t attr_size;
char path[] = "/home/user/data";
char name[] = "user.checksum";
void* value_buf = NULL;
size_t buf_len = 0;

// Retrieve attribute length (value_buf=NULL)
attr_size = getxattr(path, name, value_buf, buf_len);

// Retrieve attribute value
value_buf = malloc(attr_size);
getxattr(path, name, value_buf, attr_size);
free(value_buf);

// Directly on symlink attributes
char link_path[] = "/tmp/link";
char link_data[256];
lgetxattr(link_path, "user.meta", link_data, 256);

// Using a file descriptor
int fd = 4;
fgetxattr(fd, name, link_data, sizeof(link_data));
